<?php
// Security tests (OWASP ASVS-informed): authentication on every route, CSRF, sessions, injection, access control,
// uploads, rate limiting, reset tokens, error disclosure, headers, HTTPS-only option.
declare(strict_types=1);
$host = rtrim($argv[1] ?? 'http://127.0.0.1:8000', '/'); $base = $host . '/api'; $root = dirname(__DIR__, 2); $results = []; $jars = []; $tok = []; $bodies = [];
$cfgFile = getenv('LTI_CONFIG'); $cfg = require $cfgFile; $pdo = new PDO("mysql:host={$cfg['db']['host']};dbname={$cfg['db']['name']};charset=utf8mb4", $cfg['db']['user'], $cfg['db']['pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$one = function ($sql) use ($pdo) { $r = $pdo->query($sql)->fetch(PDO::FETCH_NUM); return $r ? $r[0] : null; };
function raw(string $m, string $url, ?string $body = null, array $h = [], ?string $jar = null): array { global $bodies; $ch = curl_init($url); curl_setopt_array($ch, [CURLOPT_CUSTOMREQUEST => $m, CURLOPT_RETURNTRANSFER => true, CURLOPT_HEADER => true, CURLOPT_HTTPHEADER => $h]);
  if ($body !== null) curl_setopt($ch, CURLOPT_POSTFIELDS, $body); if ($jar) curl_setopt_array($ch, [CURLOPT_COOKIEJAR => $jar, CURLOPT_COOKIEFILE => $jar]);
  $r = (string)curl_exec($ch); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); $hs = curl_getinfo($ch, CURLINFO_HEADER_SIZE); curl_close($ch); $b = substr($r, $hs); $bodies[] = $b; return [$c, substr($r, 0, $hs), $b]; }
function rq(string $who, string $m, string $p, $b = null, bool $csrf = true): array { global $base, $jars, $tok; $jars[$who] = $jars[$who] ?? tempnam(sys_get_temp_dir(), 'jar'); $h = ['Accept: application/json'];
  if ($csrf && !empty($tok[$who]) && $m !== 'GET') $h[] = 'X-CSRF-Token: ' . $tok[$who]; if ($b !== null) $h[] = 'Content-Type: application/json';
  [$c, $hd, $body] = raw($m, $base . $p, $b === null ? null : json_encode($b), $h, $jars[$who]); return [$c, json_decode($body, true) ?? [], $body, $hd]; }
function login(string $who, string $e, string $pw = 'Dev-Password-2026'): int { global $tok; [$c, $d] = rq($who, 'POST', '/auth/login', ['email' => $e, 'password' => $pw]); if ($c === 200) $tok[$who] = $d['csrf']; return $c; }
function t(string $n, callable $f): void { global $results; try { $results[] = [$n, true, (string)$f()]; } catch (Throwable $e) { $results[] = [$n, false, $e->getMessage()]; } }
function ok($c, string $m): void { if (!$c) throw new Exception($m); }
foreach (['own' => 'owner@lti.test', 'adv' => 'advisor@lti.test', 'adv2' => 'advisor2@lti.test', 'fin' => 'finance@lti.test', 'trv' => 'traveler@lti.test', 'trv2' => 'traveler2@lti.test'] as $k => $e) login($k, $e);
$amalfi = (int)$one("SELECT id FROM trips WHERE name='Amalfi Coast Anniversary'"); $shah = (int)$one("SELECT id FROM contacts WHERE email='shah@example.com'"); $adv = (int)$one("SELECT id FROM users WHERE email='advisor@lti.test'");
t('SEC-T01 Every API route refuses unauthenticated requests', function () use ($base) { $routes = json_decode(file_get_contents(__DIR__ . '/routes_snapshot.json'), true); $public = ['POST /auth/login', 'POST /auth/reset', 'GET /public/forms/{token}', 'POST /public/forms/{token}/submit', 'POST /cron/run', 'GET /health', 'POST /auth/logout', 'GET /auth/me'];
  $bad = []; $n = 0; foreach ($routes as [$m, $p]) { if (in_array("$m $p", $public, true)) continue; $n++; $url = $base . preg_replace('/\{[a-z]+\}/i', '1', $p); [$c] = raw($m, $url, in_array($m, ['POST', 'PUT', 'PATCH'], true) ? '{}' : null, ['Content-Type: application/json', 'Accept: application/json']); if (!in_array($c, [401, 403], true)) $bad[] = "$m $p => $c"; }
  [$me] = raw('GET', "$base/auth/me"); ok(!$bad && in_array($me, [401, 200], true), implode('; ', array_slice($bad, 0, 8))); return "$n protected routes all returned 401/403 without a session"; });
t('SEC-T02 CSRF: state-changing requests without or with a wrong token are refused', function () use ($shah) { global $tok; $r = [];
  [$r['contact create, no token']] = rq('adv', 'POST', '/contacts', ['firstName' => 'Csrf', 'email' => 'csrf@x.test'], false); [$r['task, no token']] = rq('adv', 'POST', '/tasks', ['title' => 'x'], false); [$r['call, no token']] = rq('adv', 'POST', '/calls', ['direction' => 'outbound', 'status' => 'busy', 'contactId' => $shah], false);
  $save = $tok['adv']; $tok['adv'] = str_repeat('a', 64); [$r['wrong token']] = rq('adv', 'POST', '/tasks', ['title' => 'x']); $tok['adv'] = $save;
  ok(array_unique(array_values($r)) === [403], json_encode($r)); return json_encode($r); });
t('SEC-T03 Sessions: forged cookie and logged-out session refused; cookie flags set', function () use ($base) { [$c1] = raw('GET', "$base/contacts", null, ['Cookie: LTISESSID=forged' . bin2hex(random_bytes(8)), 'Cookie: PHPSESSID=forged' . bin2hex(random_bytes(8))]);
  login('tmp', 'sales@lti.test'); [, , , $hd] = rq('tmp', 'POST', '/auth/logout'); [$c2] = rq('tmp', 'GET', '/contacts'); [$lc, , , $lh] = rq('tmp2', 'POST', '/auth/login', ['email' => 'sales@lti.test', 'password' => 'Dev-Password-2026']);
  $sc = implode("\n", preg_grep('/^set-cookie:/i', explode("\n", $lh))); ok($c1 === 401 && $c2 === 401 && $lc === 200 && stripos($sc, 'httponly') !== false && stripos($sc, 'samesite=lax') !== false, "$c1 $c2 $sc");
  return 'forged 401; after logout 401; Set-Cookie HttpOnly + SameSite=Lax (Secure is added automatically under HTTPS)'; });
t('SEC-T04 SQL injection payloads in search and filters cause no errors or data leaks', function () use ($one) { $p = ["' OR '1'='1", "1; DROP TABLE contacts; --", "\" OR 1=1 --", "%' UNION SELECT password_hash FROM users --", "1' AND SLEEP(3) --"]; $bad = []; $n0 = (int)$one('SELECT COUNT(*) FROM contacts');
  foreach ($p as $x) foreach (['/contacts?q=', '/trips?q=', '/calls?q=', '/tasks?q=', '/emails?q=', '/suppliers?q=', '/bookings?q='] as $ep) { $t0 = microtime(true); [$c, $d, $b] = rq('own', 'GET', $ep . urlencode($x)); $dt = microtime(true) - $t0;
    if (!in_array($c, [200, 422], true) || preg_match('/SQLSTATE|syntax|PDO|password_hash/i', $b) || $dt > 2.5 || ($c === 200 && ($d['total'] ?? count($d['items'] ?? [])) > 0 && strpos($x, 'UNION') !== false)) $bad[] = "$ep$x => $c " . round($dt, 1) . 's'; }
  [$c] = rq('own', 'POST', '/contacts', ['firstName' => "Robert'); DROP TABLE contacts;--", 'email' => 'bobby@x.test']); ok(!$bad && $c === 201 && (int)$one('SELECT COUNT(*) FROM contacts') === $n0 + 1, implode('; ', $bad)); return count($p) * 7 . ' payloads across 7 search endpoints: no error, no leak, no delay; payload stored as plain text'; });
$FX = [];
t('SEC-T00 Fixture: real supplier, booking, internal and client-visible documents created through the API', function () use (&$FX, $amalfi, $base) { global $jars, $tok;
  [$c1, $s] = rq('own', 'POST', '/suppliers', ['name' => 'Security Test Hotel', 'category' => 'hotel']); ok($c1 === 201, "supplier $c1 " . json_encode($s)); $sid = $s['supplier']['id'] ?? $s['id'];
  [$c2, $b] = rq('adv', 'POST', '/bookings', ['tripId' => $amalfi, 'supplierId' => $sid, 'category' => 'accommodation', 'amount' => '100.00', 'currency' => 'USD']); ok($c2 === 201, "booking $c2 " . json_encode($b)); $FX['booking'] = $b['booking']['id'] ?? $b['id'];
  $pdf = "%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj 2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj 3 0 obj<</Type/Page/Parent 2 0 R/MediaBox[0 0 10 10]>>endobj\ntrailer<</Root 1 0 R>>\n%%EOF"; $f = sys_get_temp_dir() . '/sec_fixture.pdf'; file_put_contents($f, $pdf);
  foreach (['internal', 'client'] as $vis) { $ch = curl_init("$base/documents"); curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_COOKIEFILE => $jars['adv'], CURLOPT_HTTPHEADER => ['X-CSRF-Token: ' . $tok['adv'], 'Accept: application/json'], CURLOPT_POSTFIELDS => ['file' => new CURLFile($f, 'application/pdf', "itinerary-$vis.pdf"), 'tripId' => (string)$amalfi, 'category' => 'other', 'visibility' => $vis]]);
    $r = json_decode((string)curl_exec($ch), true); $c = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); ok($c === 201, "doc $vis $c " . json_encode($r)); $FX["doc_$vis"] = $r['document']['id'] ?? $r['id']; }
  return json_encode($FX); });
t('SEC-T05 Staff access control: another advisor cannot reach real records across modules (owner positive control)', function () use (&$FX, $shah, $amalfi) { $r = []; $paths = ["/contacts/$shah", "/trips/$amalfi", "/bookings/{$FX['booking']}", "/documents/{$FX['doc_internal']}", "/documents/{$FX['doc_internal']}/download", "/activity?entityType=contact&entityId=$shah", "/contacts/$shah/phones"];
  foreach ($paths as $p) { [$own] = rq('adv', 'GET', $p); [$c] = rq('adv2', 'GET', $p); ok($own === 200, "positive control $p => $own"); $r[$p] = $c; }
  [$r['PUT trip']] = rq('adv2', 'PUT', "/trips/$amalfi", ['name' => 'hijack']); [$r['PUT booking']] = rq('adv2', 'PUT', "/bookings/{$FX['booking']}", ['notes' => 'x']);
  ok(count(array_filter($r, fn($c) => !in_array($c, [403, 404], true))) === 0, json_encode($r)); return 'owner 200 on all 7; advisor2: ' . json_encode($r); });
t('SEC-T06 Client isolation: another traveler cannot reach a client’s trips or documents (owner positive control); no staff endpoints', function () use (&$FX, $amalfi) { [, $t1] = rq('trv', 'GET', '/portal/trips'); $ids1 = array_column($t1['items'] ?? $t1['trips'] ?? [], 'id'); ok(in_array($amalfi, $ids1), 'traveler1 does not own Amalfi: ' . json_encode($ids1));
  [$pos] = rq('trv', 'GET', "/portal/documents/{$FX['doc_client']}/download"); [$posInt] = rq('trv', 'GET', "/portal/documents/{$FX['doc_internal']}/download"); ok($pos === 200 && in_array($posInt, [403, 404], true), "traveler1 client doc $pos, internal doc $posInt");
  $r = []; [$r['trv2 -> trip']] = rq('trv2', 'GET', "/portal/trips/$amalfi"); [$r['trv2 -> client doc']] = rq('trv2', 'GET', "/portal/documents/{$FX['doc_client']}/download"); [$r['trv2 approve']] = rq('trv2', 'POST', "/portal/trips/$amalfi/approve", []);
  foreach (['/contacts', '/trips', '/invoices', '/calls', '/tasks', '/staff', "/documents/{$FX['doc_client']}"] as $p) { [$c] = rq('trv', 'GET', $p); $r["trv $p"] = $c; }
  ok(count(array_filter($r, fn($c) => !in_array($c, [403, 404], true))) === 0, json_encode($r)); return "traveler1 downloads own client document (200) but not the internal one ($posInt); " . json_encode($r); });
t('SEC-T07 Privilege escalation refused', function () use ($adv) { $own = (int)$GLOBALS['one']("SELECT r.id FROM roles r WHERE code='owner'"); $r = [];
  [$r['advisor PATCH own role']] = rq('adv', 'PATCH', "/staff/$adv", ['roleId' => $own, 'role' => 'owner']); [$r['finance staff list']] = rq('fin', 'GET', '/staff'); [$r['advisor reset link']] = rq('adv', 'POST', "/staff/$adv/reset-link");
  [$r['advisor workflows']] = rq('adv', 'POST', '/workflows', ['name' => 'x', 'triggerType' => 'trip.created', 'actions' => [['type' => 'timeline', 'params' => ['text' => 'x']]]]); [$r['advisor void']] = rq('adv', 'POST', '/invoices/1/void', ['reason' => 'x']);
  ok(count(array_filter($r, fn($c) => !in_array($c, [403, 404], true))) === 0 && $GLOBALS['one']("SELECT r.code FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=$adv") === 'advisor', json_encode($r)); return json_encode($r); });
t('SEC-T08 Unsafe uploads refused; stored files are outside the web root', function () use ($base, $amalfi, $root) { global $jars, $tok; $tmp = sys_get_temp_dir(); $cases = ['shell.pdf' => '<?php system($_GET["c"]); ?>', 'shell.phtml' => '<?php echo 1;', 'shell.php.pdf' => "<?php echo 1; ?>\n%PDF-1.4", 'x.svg' => '<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>', '.htaccess' => 'SetHandler application/x-httpd-php', 'x.exe' => "MZ\x90\x00"]; $r = [];
  foreach ($cases as $name => $content) { $f = "$tmp/$name"; file_put_contents($f, $content); $ch = curl_init("$base/documents"); curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_COOKIEFILE => $jars['adv'], CURLOPT_HTTPHEADER => ['X-CSRF-Token: ' . $tok['adv'], 'Accept: application/json'], CURLOPT_POSTFIELDS => ['file' => new CURLFile($f, 'application/pdf', $name), 'tripId' => (string)$amalfi, 'category' => 'Other']]);
    curl_exec($ch); $r[$name] = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); }
  $storage = realpath($root . '/server/app/storage'); $public = realpath($root . '/server/public'); ok(count(array_filter($r, fn($c) => $c < 400)) === 0 && strpos($storage, $public) !== 0, json_encode($r)); return json_encode($r) . '; storage outside public/'; });
t('SEC-T09 Sign-in rate limiting', function () { $codes = []; for ($i = 0; $i < 12; $i++) { $codes[] = login('rl', 'operations@lti.test', 'wrong-' . $i); } $after = login('rl2', 'operations@lti.test');
  ok(in_array(429, $codes, true) && $after === 429, json_encode([$codes, $after])); return 'locked after ' . (array_search(429, $codes) + 1) . ' attempts; correct password also refused while locked'; });
t('SEC-T09b A locked account does not lock out colleagues on the same network; spraying many accounts from one IP is still stopped', function () use ($pdo) {
  $other = login('rl3', 'supervisor@lti.test'); $pdo->exec("DELETE FROM login_attempts"); $codes = []; for ($i = 0; $i < 32; $i++) $codes[] = login('spray', "nobody$i@example.test", 'guess');
  $after = login('rl4', 'admin@lti.test'); ok($other === 200 && in_array(429, $codes, true) && $after === 429, json_encode([$other, array_search(429, $codes), $after]));
  $pdo->exec("DELETE FROM login_attempts"); return 'colleague signs in while operations@ is locked (200); IP blocked after ' . (array_search(429, $codes) + 1) . ' failures across different accounts'; });
t('SEC-T10 Password reset links are single-use and expire', function () use ($pdo) { $sid = (int)$GLOBALS['one']("SELECT id FROM users WHERE email='sales@lti.test'"); [$c, $d] = rq('own', 'POST', "/staff/$sid/reset-link"); parse_str((string)parse_url(str_replace('#/reset?', '?', $d['resetUrl']), PHP_URL_QUERY), $q); $t = $q['token'];
  [$c1] = rq('anon', 'POST', '/auth/reset', ['token' => $t, 'password' => 'New-Strong-Pass-2026!']); [$c2] = rq('anon', 'POST', '/auth/reset', ['token' => $t, 'password' => 'Another-Pass-2026!']);
  [, $d2] = rq('own', 'POST', "/staff/$sid/reset-link"); parse_str((string)parse_url(str_replace('#/reset?', '?', $d2['resetUrl']), PHP_URL_QUERY), $q2); $pdo->exec("UPDATE password_resets SET expires_at=UTC_TIMESTAMP() - INTERVAL 1 MINUTE WHERE used_at IS NULL"); [$c3] = rq('anon', 'POST', '/auth/reset', ['token' => $q2['token'], 'password' => 'Expired-Pass-2026!']);
  ok($c === 200 && $c1 === 200 && $c2 >= 400 && $c3 >= 400, "$c $c1 $c2 $c3"); return "first use 200; reuse $c2; expired $c3"; });
t('SEC-T11 Errors disclose no internals; security headers on API and app', function () use ($base, $host) { [$c1, , $b1] = raw('POST', "$base/contacts", '{bad json', ['Content-Type: application/json']); [$c2, , $b2] = raw('GET', "$base/no/such/route"); [, $ah] = raw('GET', "$base/auth/me"); [, $sh] = raw('GET', "$host/");
  global $bodies; $leak = array_filter($bodies, fn($b) => preg_match('/Stack trace|SQLSTATE|PDOException|\/home\/|\.php on line|Fatal error/i', $b));
  foreach (['x-frame-options: deny', 'referrer-policy', "content-security-policy: default-src 'none'"] as $hh) ok(stripos($ah, $hh) !== false, "API header $hh"); foreach (['x-frame-options: deny', "frame-ancestors 'none'", 'x-content-type-options: nosniff'] as $hh) ok(stripos($sh, $hh) !== false, "app header $hh");
  ok(!$leak && stripos($ah . $sh, 'x-powered-by') === false, 'leak: ' . substr((string)reset($leak), 0, 160)); return count($bodies) . ' responses scanned: no stack traces, SQL errors or paths; headers present; no X-Powered-By'; });
t('SEC-T12 HTTPS-only sign-in option refuses plain HTTP', function () use ($cfg, $root) { $c = $cfg; $c['require_https'] = true; $f = sys_get_temp_dir() . '/cfg_https.php'; file_put_contents($f, '<?php return ' . var_export($c, true) . ';');
  shell_exec('(LTI_CONFIG=' . escapeshellarg($f) . " setsid nohup php -S 127.0.0.1:8002 -t $root/server/public $root/server/dev-router.php </dev/null >/dev/null 2>&1 &)"); sleep(1);
  [$code, , $b] = raw('POST', 'http://127.0.0.1:8002/api/auth/login', json_encode(['email' => 'owner@lti.test', 'password' => 'Dev-Password-2026']), ['Content-Type: application/json']); shell_exec("pkill -f '[1]27.0.0.1:8002'");
  ok($code === 403 && strpos($b, 'HTTPS') !== false, "$code $b"); return '403 “Sign-in requires a secure (HTTPS) connection.”'; });
$pdo->exec('DELETE FROM login_attempts'); // teardown (test database): do not affect later suites
$pass = count(array_filter($results, fn($r) => $r[1])); foreach ($results as [$n, $o, $d]) echo ($o ? 'PASS ' : 'FAIL ') . "$n — $d\n"; echo "SECURITY SUMMARY $pass/" . count($results) . "\n";
file_put_contents(__DIR__ . '/api_security_results.json', json_encode($results, JSON_PRETTY_PRINT)); exit($pass === count($results) ? 0 : 1);
